-- Девять записей журнала обновлений (ADR 0077): выпуски 19–23 и четыре подверсии выпуска 18.
--
-- Схему миграция не трогает — она только заводит записи выпусков, как 0102, 0109, 0113, 0116, 0125,
-- 0126, 0128, 0134, 0135 и 0140 (ADR 0077 §4).
--
-- Почему сразу девять. Журнал отстал от main на четыре дня плотной работы (14–18 августа) и на
-- хвосты 10–14 августа, не доехавшие до своих выпусков. Правило «выпуск — блок работы, а не отрезок
-- календаря» (§1) при этом не нарушено: блоки нарезаны по темам, а не по дням, и часть их поэтому
-- датирована задним числом — дата у записи справочная, порядок задаёт `seq`.
--
-- Почему четыре подверсии подряд. У четырёх блоков последнее решение старше уже опубликованного
-- хвоста `0108` (ADR 0089–0098, 0107), а у двух из них своего решения нет вовсе: почтовые каналы,
-- парк в модуле и история единицы сделаны по уже принятым ADR 0096 и 0097, продолжение ездок — по
-- ADR 0108, названному выпуском 18. Четырёхзначный хвост здесь либо назвать нечем, либо он сломал бы
-- монотонность, ради которой заведён (§2). Тот же размен, что в подверсиях `0.1.10.1`, `0.1.16.1` и
-- `0.1.18.1`.
--
-- Даты стоят по выкладке самой работы, а не по дню, когда она доехала до журнала: пользователю
-- `released_on` отвечает на вопрос «с какого числа это работает», и подверсия с хвостами 10–12
-- августа честнее датируется двенадцатым. Отсюда единственный случай, когда дата у следующей записи
-- меньше, чем у предыдущей (`seq` 21 после `seq` 20): порядок здесь и задаётся `seq`, а дата его не
-- задаёт (§3) — ради этого разделения оба поля и заведены.
--
-- ADR 0078 (ролевые сводки) отдельной записи не получает намеренно: рассылки переделаны ADR 0093, и
-- пользователю они уже рассказаны подверсией `0.1.16.1` — в том виде, в котором работают сейчас.
-- Запись про их прежний вид была бы историей разработки, а не журналом обновлений.
--
-- Номер миграции 0159, а не 0158: 0158 занят параллельным потоком работы (справочник руководств,
-- `docs/manuals-plan.md`). Номер берётся с конца, а не вставляется в середину — тот же размен, что в
-- 0113, 0125, 0126 и 0140.

-- Подверсия 1: хвосты 10–12 августа. ADR 0089, 0090, 0091, 0098.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  21, '0.1.18.2', '2026-08-12', 'Неделя в общем списке заказов, переоформление заявки и отбор по машине', '{89,90,91,98}',
  '[
    {"kind":"feature","text":"Недельная заявка переехала в общий список «Заказ автотехники»: своей вкладки у неё больше нет, документы идут одной лентой, а вид читается по номеру — «НЗ-12». Читать неделю может каждый, кто видит заказы этой площадки: наблюдатель, обе роли отдела и арендодатель — последнему видны его строки и счётчики по ним, а не весь состав"},
    {"kind":"feature","text":"Каждая следующая неделя начинается с прошлой: годные позиции приходят отмеченными к продлению, а выбывшие названы поимённо — «Из НЗ-15: 6 продлеваются, 2 выбыли». Раньше исчезнувшая позиция читалась как ошибка портала, и штаб заводил её второй строкой"},
    {"kind":"improvement","text":"Единица, у которой уже оформлен вывоз, которая стоит строкой «уезжает» в другой неделе или ждёт решения по досрочному отъезду, в состав не берётся — и уходит в список «не годятся» с причиной, а не пропадает молча"},
    {"kind":"improvement","text":"Воскресенье входит в неделю: заказ, кончающийся ровно в воскресенье, виден в составе, и по нему принимают решение «уезжает». Раньше портал считал такую машину заказанной дольше недели и убирал её из сборки"},
    {"kind":"feature","text":"Новую заявку на грузовой технике можно переоформить в другой тип — грузоперевозку в заказ техники на объект и обратно. Номер, автор, вложения и история остаются за заявкой; переносятся день и контакт на месте, остальное форма не выдумывает: у другого типа этих полей либо нет, либо они означают другое"},
    {"kind":"improvement","text":"Переоформление снимает визу и пишет своё событие истории — со сроками обеих сторон сразу, чтобы «Подача: — → 12.08» не читалось как потеря данных. Заказ, созданный недельной заявкой, после переоформления неделя больше не ведёт, а обратное переоформление связь возвращает"},
    {"kind":"improvement","text":"Регистрация с личного ящика предупреждает, но не отказывает: заявка уходит администратору как любая другая, а у нерассмотренных заявок в списке учёток стоит пометка «Внешняя почта». Операторам вывоза мусора и аренды техники предупреждение не показывается — рабочего адреса компании у них не бывает"},
    {"kind":"improvement","text":"В заявках появился отбор по назначенной машине — рядом с прежним отбором по типу и категории, который теперь честно подписан «Любой тип ТС». Машина выбирается строкой «госномер — марка/модель», арендная — «описание — арендодатель», и фильтр работает в списке, ленте, архиве, «Истории» и сводке над таблицей"}
  ]'::jsonb
);

-- Подверсия 2: линейная техника под работающими заказами. ADR 0107, миграция 0137.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  22, '0.1.18.3', '2026-08-14', 'Линейная техника: признак переключается под работающими заказами', '{107}',
  '[
    {"kind":"feature","text":"Признак «Линейная техника» у типа ТС теперь переключается, даже когда по этому типу идут заказы. Прежний запрет был недостижим ровно для той техники, ради которой признак заводился: автовышки, катки и поливомоечные работают сплошным потоком, и окна без единого действующего заказа у них не бывает"},
    {"kind":"improvement","text":"Заказы, застигнутые переключением в работе, остаются на прежнем режиме документооборота до закрытия: недельный ЭСМ-2 не превращается в дневные 4-П посреди срока. Переключение называет их до нажатия — сколько заказов останется по-старому и какие именно"},
    {"kind":"improvement","text":"Откат заказа из «Выполнена» в «В работе» тоже спрашивает подтверждения и называет последствия: заморозка снята закрытием, и вернувшаяся заявка пойдёт по нынешнему режиму справочника — с перечнем недель ЭСМ-2, которые придётся выписать или снять"},
    {"kind":"fix","text":"Обычной правкой карточки типа признак больше не меняется — только своим окном с предпросмотром: молчаливая галочка сменила бы режим работающим заказам мгновенно, а отказ теперь называет, где переключение живёт"}
  ]'::jsonb
);

-- Подверсия 3: почта модулей и парк орг.техники. Продолжение ADR 0096 и 0097, миграции 0141–0144.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  23, '0.1.18.4', '2026-08-14', 'Орг.техника: письмо службе, парк в модуле и история единицы', '{96,97}',
  '[
    {"kind":"feature","text":"Заявка на обслуживание доходит до службы письмом: она читает почту, а не портал. Письмо уходит на входе заявки в статус — и когда её завели, и когда административный откат вернул её из «Согласована ИТ» или из «Отменена», — а отмена сообщается отдельно, чтобы за заявкой не выезжали зря. Срочность видна в теме"},
    {"kind":"improvement","text":"Ответ портала называет и судьбу письма: «заявка заведена, но служба не оповещена» человек узнаёт сразу, а не когда за ней не приехали. Рядом стоит повтор отправки — два нажатия дают одно письмо, осознанный второй заход новое"},
    {"kind":"feature","text":"Письма модулей уходят вторым почтовым каналом — с ящика самой службы на её сервере: чужого отправителя почтовые службы отвергают. У каждого канала свой сервер, своя учётка и свой предел писем в минуту, а ненастроенный канал откладывает только свои письма — остальные идут своим ходом"},
    {"kind":"improvement","text":"У письма появился свой обратный адрес: ответ на письмо службе уходит заявителю, а не в ящик, из которого письмо пришло"},
    {"kind":"improvement","text":"Вкладка «Рассылки» разрезана на три подвкладки — расписания, служебные адреса и отладка: раньше блоки шли одним свитком и вместе в экран не помещались. Отладочная отправка выбирает канал — единственный способ проверить новый сервер до первого настоящего события"},
    {"kind":"feature","text":"В модуле «Орг.техника» появилась вкладка «Техника» — парк глазами того, кто его эксплуатирует: где что стоит, что уехало в ремонт, откуда переехало. Заведение и правка карточек остались справочнику, здесь — состояние, перемещение и история"},
    {"kind":"improvement","text":"Раздел открывают два права вместо одного: менеджеру и диспетчеру, у которых орг.техника есть, а модуля заявок нет, вкладка больше не за закрытой дверью. Сервисной компании парк по-прежнему закрыт — реквизиты нужной ей единицы приходят снимком в самой заявке"},
    {"kind":"feature","text":"История единицы собирается из шести источников одним потоком: перемещения, заявки и их ключевые шаги, правки карточки, гарантии и заведение самой карточки. В шапке — где стоит сейчас, за кем числится и до какого числа гарантия; всю ленту можно выгрузить в .xlsx"},
    {"kind":"improvement","text":"Гарантии перестали теряться: выданная при закрытии заявки гарантия остаётся в истории и после того, как следующий ремонт перепишет срок в карточке. Раньше на вопрос «что нам обещали в марте» ответить было нечем"},
    {"kind":"feature","text":"Справочник орг.техники наполнен: 353 МФУ на 25 площадках, включая семь объектов, которых в портале ещё не было"}
  ]'::jsonb
);

-- Подверсия 4: ездки заработали. Продолжение ADR 0108, миграция 0146.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  24, '0.1.18.5', '2026-08-17', 'Ездки в заявке заработали: задание строками, порядок объезда и выписка с подтверждением', '{108}',
  '[
    {"kind":"feature","text":"Заявка на перевозку заводится списком ездок: у каждой свой груз, своё время и свои адреса. Карточка заказа собирается ими же, а не одной парой адресов на всю заявку"},
    {"kind":"feature","text":"Маршрут собирается точками: остановка заводится один раз, а работы на ней выстраиваются порядком, который задаёт диспетчер. Раньше порядок объезда выводился из номеров заявок, и две работы на одной паре адресов расходились не там, где нужно людям"},
    {"kind":"improvement","text":"Точку можно править и разделять, не пересобирая рейс, а перестановка состава двигает и точки: иначе стрелки показывали один порядок, а бумага печатала другой"},
    {"kind":"feature","text":"Задание в путевом листе печатается строками — ездка или день линейного заказа, — и адреса в нём стоят от точек маршрута: в документе водителя должно быть то место, куда он приедет и где его встретят. Те же строки видны в карточке до выписки: диспетчер видит порядок, который придёт водителю"},
    {"kind":"improvement","text":"Выписка листа перестала быть молчаливой: то, что мешает выписать, отвечает отказом до того, как израсходован номер бланка, а спорное — расхождение адреса, пробелы в документах водителя, несколько объектов затрат в листе — спрашивает подтверждения. Проверка стоит на сервере, а не в окне: старая вкладка и повтор запроса из истории выписывали лист мимо неё"},
    {"kind":"improvement","text":"Закрыт пятый путь выпуска номера: ЭСМ-2 «по требованию» брал бланк своим счётчиком и оставлял в листе «не проверяли». Теперь «проверено, чисто» и «не проверяли» различаются в данных, а не подразумеваются"},
    {"kind":"fix","text":"Перенос рейса на другой день двигает и время ездок: до этого заявка после переноса переставала сохраняться, а кабинет водителя показывал работу не того дня"},
    {"kind":"fix","text":"Перенос заявки между рейсами раскладывает её точками — перевыписанный лист умалчивал о переехавшей работе"},
    {"kind":"fix","text":"Обычный длинный адрес больше не отказывает в выписке: блокирует теперь только патология, остальное режется в бланке видимо, с многоточием, а полный адрес водитель получает в задании целиком"},
    {"kind":"fix","text":"Кабинет водителя открывается: после перевода задания на точки страница читала его по-старому и падала на первом же открытии. Задание идёт остановками — роль на остановке, номер ездки, заказчик, записка диспетчера и комментарий строки"},
    {"kind":"fix","text":"Количество груза в кабинете снова не печатается: цифру водитель сверяет на весах, а строки на остановке различает номер ездки — «ТС-101/1» и «ТС-101/2»"},
    {"kind":"fix","text":"Администратор больше не проваливается в кабинет водителя: вход спрашивает роль, а не одно право, которое у администратора есть по построению. Раньше заход на корень портала уводил его в кабинет, из которого выхода не предусмотрено"}
  ]'::jsonb
);

-- Выпуск 19: показания техники. ADR 0110, миграции 0147 и 0148.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  25, '0.1.19.0110', '2026-08-17', 'Показания: приём, статистика и ТО по пробегу', '{110}',
  '[
    {"kind":"feature","text":"У показаний появился экран приёма: реестр смен, по которому видно, кто сдал, кто нет и где расхождение. Отчёт принимается целиком, а разбирается на месте — внести за работника, подтвердить аномалию, поправить порядок смен, перенести показание на другую дату"},
    {"kind":"improvement","text":"Считается всё от ожидаемых смен, а не от заведённых строк: рейс с действующим листом именно на своего водителя и каждый день недельного ЭСМ-2. Раньше день водителя без учётной записи выглядел в сводке полным — строка рождалась только при открытии дня"},
    {"kind":"feature","text":"Карточка машины: итог за период, разбивка по месяцам с диаграммой, журнал показаний страницами и качество данных цифрами рядом с итогом — сколько смен ожидалось, сколько без показаний, сколько не принято. Неполнота названа числом, а не спрятана"},
    {"kind":"feature","text":"Техобслуживание ведётся по пробегу: журнал актов, норматив 10 000 км и «пробег с ТО», посчитанный цепочкой приростов от акта, а не вычитанием счётчиков. Замена прибора больше не даёт минуса и не запрещает следующее ТО"},
    {"kind":"improvement","text":"В гараже появились колонки одометра и ТО, а выгрузок стало шесть — от сводки по парку до построчного журнала. Слишком широкий период отвечает «сузьте», а не молча обрезанным файлом"},
    {"kind":"improvement","text":"Права на обслуживание и права на показания разведены: механик ведёт журнал ТО и видит скан акта, не открывая приёмку, журналы и фотографии показаний"},
    {"kind":"improvement","text":"Перенесённый рейс оставляет своё число в прежнем месяце и просит показание на новой дате: у смены две координаты, и портал больше не сворачивает их в одну"}
  ]'::jsonb
);

-- Выпуск 20: реформа доступа. ADR 0106, 0111, 0112, 0113, миграции 0138, 0145, 0149–0156.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  26, '0.1.20.0113', '2026-08-18', 'Доступ собирается из должности и полномочий', '{106,111,112,113}',
  '[
    {"kind":"feature","text":"Между ролью и правом появился второй источник — назначаемое полномочие: администратор собирает набор прав в конструкторе и выдаёт его поимённо. Чтобы дать человеку одно действие, больше не нужно выдавать ему всю роль целиком, а роли — множиться под каждую должность"},
    {"kind":"feature","text":"Витрина «Права» отвечает, откуда у учётки взялось каждое право: роль, полномочие или то и другое сразу. Раньше на этот вопрос не отвечал никто"},
    {"kind":"improvement","text":"Выдача идёт через предпросмотр: портал называет, что именно изменится у затронутых учёток, и отклоняет подтверждение, если между показом и нажатием состав набора или права людей успели измениться"},
    {"kind":"improvement","text":"Свобода сборки набора ограничена барьерами: пять прав полномочием не выдаются вовсе, часть прав требует других, конфликты обязанностей считаются по итоговым правам учётки, а матрица «ось роли и модуль» не даёт набору с чтением путевых листов открыть площадке листы всей компании"},
    {"kind":"feature","text":"Руководство отделом перестало быть ролью и стало признаком связи «человек и отдел»: в одном отделе человек руководитель, в другом сотрудник — роль такого различить не может. Ставится оно в справочнике «Отделы», и роль «Руководитель отдела» сама по себе руководителем больше не делает"},
    {"kind":"improvement","text":"Ролевые рассылки адресуются правом, а не названием роли: кому нужна сводка — вопрос о работе, а не о должности. Расписание, которому нечего противопоставить, осталось без адресации и названо поимённо — приближение здесь меняло бы аудиторию молча"},
    {"kind":"improvement","text":"Заведена роль «Площадка» и три ролевых набора к ней: из них собираются нынешние «Штаб» и «Руководитель строительства». Учёток у неё пока нет — перевод идёт отдельным выпуском, и доступ ни у одной живой учётки этим выпуском не изменился"},
    {"kind":"improvement","text":"Вход в упраздняемые роли закрыт: завести учётку на «Штабе» и «Руководителе строительства» больше нельзя, а пожелания при регистрации нацелены на «Площадку». Уже работающие учётки остаются на своих ролях до перевода"},
    {"kind":"feature","text":"Появились две роли вокруг парка: механик смотрит справочники, гараж, журнал листов и карточки водителей, а главный механик сверх этого ведёт водителей и списывает испорченный бланк. Своей площадки у службы нет намеренно — она отвечает за технику компании, а не за объект"},
    {"kind":"improvement","text":"Диспетчеру добавлены возврат заявки в «Новую» и рассылки: чинит и рассылает тот, кому звонят, — раньше ради этого ждали рабочего дня администратора"},
    {"kind":"fix","text":"Возврат записи из архива спрашивает область: право на архив поднимало карточку по одному номеру, в обход прав на сам модуль, — а возврат на живой записи просто отдаёт её целиком. Сегодняшний доступ при этом не изменился ни у кого: у всех, у кого право есть, области нет"},
    {"kind":"fix","text":"Отказ при откате статуса больше не говорит «может только администратор»: право есть и у диспетчера, а полномочием приезжает любому, кому его выдали"}
  ]'::jsonb
);

-- Выпуск 21: смена техники вместе с человеком. ADR 0115.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  27, '0.1.21.0115', '2026-08-18', 'Смена техники сажает за руль другого человека', '{115}',
  '[
    {"kind":"feature","text":"В окне смены назначенной техники появились машинист и водитель: за другой единицей на площадку выходит другой человек, и приезжают они вместе. Раньше машиниста меняли перевыпиской листов ЭСМ-2 руками, а водителя — лишним маршрутом «с нужным именем», и тот оставался пустой записью в плане дня"},
    {"kind":"improvement","text":"Водитель ставится на весь состав рейса или снимается с него; рейс, замороженный выписанным листом, смену отклоняет, удалённый из справочника водитель в подбор не попадает, а сама смена уходит в тот же журнал, что и обычная правка рейса"},
    {"kind":"improvement","text":"Прежнее имя портал не подставляет: оно стоит подсказкой под полем, а пустое поле значимо и означает «оставить прежнего». Подставленная фамилия доехала бы до бланка настоящей"}
  ]'::jsonb
);

-- Выпуск 22: просроченная недельная заявка. ADR 0116, миграция 0157.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  28, '0.1.22.0116', '2026-08-18', 'Просроченная неделя проводится задним числом', '{116}',
  '[
    {"kind":"feature","text":"Недельная заявка, чья неделя успела начаться, перестала быть тупиком: её заводят, подают и проводят задним числом. Раньше подать такую заявку было нельзя, завизировать нельзя, а техника эти дни уже отработала — площадка либо договаривалась мимо портала, либо заводила неделю сегодняшней датой, в которой написано не то, что было"},
    {"kind":"improvement","text":"Проводит такую неделю тот, у кого есть право прошлого, — диспетчер и администратор: у просроченной недели право визы подменяется. Руководитель площадки её больше не проводит, но по-прежнему отклоняет: отказ в прошлом ничего не двигает"},
    {"kind":"improvement","text":"Виза становится операцией коррекции: обязательная причина, тридцать дней вглубь (у администратора без предела) и своя строка в журнале коррекций. Листы ЭСМ-2 прошедших недель выписываются тем же контекстом, а листы уже отработанных недель называются к перевыписке поимённо"},
    {"kind":"improvement","text":"Экран вместо погашенных кнопок объясняет: чем операция обойдётся и в каком окне проводится, а тому, у кого права нет, — к кому идти. Кнопка «Снять заявку» больше не прячется: сервер разрешал её всегда"}
  ]'::jsonb
);

-- Выпуск 23: журнал учётных записей. ADR 0109 и 0117.
INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  29, '0.1.23.0117', '2026-08-18', 'Аудит учёток: журнал изменений и свой срез', '{109,117}',
  '[
    {"kind":"feature","text":"Подвкладка «Аудит» стала журналом изменений: событие несёт пары «было и стало» по всем полям учётки — роль, доступ, ФИО, телефон, адрес, объекты, отделы, контрагент, полномочия, работник. Раньше лента перечисляла действия администраторов, не говоря, что именно поменялось"},
    {"kind":"improvement","text":"Лента отбирается по данным самих учёток: роль, доступ, объект, отдел, контрагент, архив тремя положениями и поиск по ФИО и адресу. Отбор идёт по нынешнему состоянию учётки — снимка на момент события журнал не хранит"},
    {"kind":"improvement","text":"Путь учётки — от заявки на регистрацию до нынешнего состояния — открывается панелью прямо из строки журнала и пунктом «История» в списке, не уводя со списка"},
    {"kind":"fix","text":"Журнал показывает свои события, а не весь портал: пустой набор галочек означал «фильтра нет», и первое же открытие вкладки выкладывало заявки, технику, справочники и тысячи входов. Границу теперь задаёт сервер, а фильтр перечисляет ровно то, что показывает лента, — включая выдачу и отзыв полномочия"},
    {"kind":"improvement","text":"У записей, сделанных до этой переделки, значения полей помечены «значения не сохранены»: задним числом журнал не дописывается"}
  ]'::jsonb
);
